import { Injectable } from '@angular/core';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { Observable, firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { BatchColumnsRes, BatchDownloadReq, BatchDownloadRes, BatchUploadReq } from '../../interfaces/batchfile.interface';

@Injectable({
  providedIn: 'root'
})
export class BatchfileService {

  constructor(public sStore: SecureStorageService, private http: HttpClient, public tost: TostbarService) { }


  async downloadBatchfile(mdl: BatchDownloadReq): Promise<boolean> {
    try {
      let res: BatchDownloadRes = await firstValueFrom(
        this.http.post<any>(
          `${environment.batchfileservice}/batch/getbatchfile`,
          mdl
        )
      );
      if (res && res.msg == 1) {
        // this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      console.error(err)
      return false;
    }

  }




  async uploadBatchfile(mdl: BatchUploadReq): Promise<boolean> {
    try {
      let res: BatchDownloadRes = await firstValueFrom(
        this.http.post<any>(
          `${environment.batchfileservice}/batch/uploadbatchfile`,
          mdl
        )
      );
      if (res && res.msg == 1) {
        // this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      console.error(err)
      return false;
    }

  }

  downloadFile(cPath: string): Observable<Blob> {
    let params = new HttpParams()
    params = params.set('cPath', cPath);
    const headers = new HttpHeaders().set('Content-Type', 'application/json');

    return this.http.get(`${environment.batchfileservice}/batch/download`, {
      params: params,
      headers: headers,
      responseType: 'blob' // Important to specify blob as the response type
    });
  }



  async getBatchcolumns(nCaseid: string, nSectionid: string): Promise<BatchColumnsRes[]> {


    try {
      let params = new HttpParams();
      params = params.set('nSectionid', nSectionid);
      params = params.set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<BatchColumnsRes[]>(
          `${environment.batchfileservice}/batch/filecolumns`,
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return [];
    }
  }




  async getFilecolumn(filepath): Promise<BatchDownloadRes> {
    try {
      let params = new HttpParams().set('cPath', filepath);
      const res: any = await firstValueFrom(
        this.http.get<BatchDownloadRes>(
          `${environment.batchfileservice}/batch/uploadedfilecols`,
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return { msg: -1 };
    }
  }

  async getBatchLog(nCaseid): Promise<BatchDownloadRes> {
    try {
      let params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<BatchDownloadRes>(
          `${environment.batchfileservice}/batch/getbatchlog`,
          { params: params }
        )
      );

      return res[0];
    } catch (err) {
      return { msg: -1 };
    }
  }


  async getBatchLogDetail(nBlogid): Promise<BatchDownloadRes> {
    try {
      let params = new HttpParams().set('nBlogid', nBlogid);
      const res: any = await firstValueFrom(
        this.http.get<BatchDownloadRes>(
          `${environment.batchfileservice}/batch/getbatchlogdetail`,
          { params: params }
        )
      );

      return res;
    } catch (err) {
      return { msg: -1 };
    }
  }


}
